#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int* findAnagrams(char* s, char* p, int* returnSize) {
    int need[26] = {0};
    int window[26] = {0};
    int m = (int)strlen(p);
    int n = (int)strlen(s);

    *returnSize = 0;
    if (m > n) return NULL;

    for (int i = 0; i < m; ++i) need[p[i] - 'a']++;

    int capacity = n - m + 1;
    int* result = (int*)malloc((size_t)capacity * sizeof(int));
    if (!result) return NULL;

    for (int i = 0; i < n; ++i) {
        window[s[i] - 'a']++;

        if (i >= m) {
            window[s[i - m] - 'a']--;
        }

        if (i >= m - 1) {
            int same = 1;
            for (int j = 0; j < 26; ++j) {
                if (window[j] != need[j]) {
                    same = 0;
                    break;
                }
            }
            if (same) result[(*returnSize)++] = i - m + 1;
        }
    }

    if (*returnSize == 0) {
        free(result);
        return NULL;
    }
    return result;
}

static int parse_quoted(const char* line, int* pos, char* out, int max_len) {
    int i = *pos;
    while (line[i] == ' ' || line[i] == ',') ++i;
    if (line[i] != '"') return 0;
    ++i;
    int k = 0;
    while (line[i] && line[i] != '"' && k < max_len - 1) {
        if (line[i] == '\\' && line[i+1]) ++i;
        out[k++] = line[i++];
    }
    if (line[i] != '"') return 0;
    out[k] = '\0';
    *pos = i + 1;
    return 1;
}

