class Solution {
    public List<Integer> findAnagrams(String s, String p) {
        int[] need = new int[26];
        int[] window = new int[26];

        for (int i = 0; i < p.length(); i++) {
            need[p.charAt(i) - 'a']++;
        }

        int m = p.length();
        List<Integer> result = new ArrayList<>();
        if (m > s.length()) return result;

        for (int i = 0; i < s.length(); i++) {
            window[s.charAt(i) - 'a']++;

            if (i >= m) {
                window[s.charAt(i - m) - 'a']--;
            }

            if (i >= m - 1) {
                boolean same = true;
                for (int j = 0; j < 26; j++) {
                    if (window[j] != need[j]) {
                        same = false;
                        break;
                    }
                }
                if (same) result.add(i - m + 1);
