    static String[] parseArgs(String line) {
        line = line.trim();
        if (line.length() < 2) throw new IllegalArgumentException("Invalid input");
        List<String> vals = new ArrayList<>();
        int i = 1;
        while (i < line.length() - 1) {
            while (i < line.length() - 1 && (line.charAt(i) == ' ' || line.charAt(i) == ',')) i++;
            if (line.charAt(i) != '"') throw new IllegalArgumentException("Expected string");
            i++;
            StringBuilder sb = new StringBuilder();
            while (i < line.length() - 1) {
                char c = line.charAt(i++);
                if (c == '"') break;
                if (c == '\\' && i < line.length() - 1) {
                    sb.append(line.charAt(i++));
                } else {
                    sb.append(c);
                }
            }
            vals.add(sb.toString());
            while (i < line.length() - 1 && (line.charAt(i) == ' ' || line.charAt(i) == ',')) i++;
        }
        return vals.toArray(new String[0]);
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] vals = parseArgs(br.readLine());
        List<Integer> result = new Solution().findAnagrams(vals[0], vals[1]);
        StringBuilder out = new StringBuilder("[");
        for (int i = 0; i < result.size(); i++) {
            if (i > 0) out.append(',');
            out.append(result.get(i));
        }
        out.append(']');
        System.out.println(out);
    }
}

